# FV-Julia 예제 6: Lambda & Closures
# ==========================================

function main(): Void =
  # Lambda 기본: 익명 함수
  let add = fn(a: Int, b: Int) -> Int { a + b }
  println("Lambda add(5, 3) = " + add(5, 3).to_string())

  # Map with lambda
  let numbers = [1, 2, 3, 4, 5]
  let doubled = numbers.map(fn(x: Int) -> Int { x * 2 })
  println("Doubled: " + doubled.to_string())

  # Closure: 외부 변수 캡처
  let multiplier = 10
  let multiply = fn(x: Int) -> Int { x * multiplier }
  println("Multiply 5 by 10 = " + multiply(5).to_string())

  # Filter with lambda
  let evens = numbers.filter(fn(x: Int) -> Bool { x % 2 == 0 })
  println("Even numbers: " + evens.to_string())

  # Reduce with lambda
  let sum = numbers.reduce(0, fn(acc: Int, x: Int) -> Int { acc + x })
  println("Sum of [1,2,3,4,5] = " + sum.to_string())

  # Higher-order function
  let compose = fn(f: Function, g: Function) -> Function {
    fn(x: Int) -> Int { f(g(x)) }
  }

  let add_one = fn(x: Int) -> Int { x + 1 }
  let times_two = fn(x: Int) -> Int { x * 2 }
  let add_one_then_double = compose(times_two, add_one)

  println("Compose (add 1, then *2): " + add_one_then_double(5).to_string())
end

