package main

import (
	"fmt"
	"strings"
)

// ==========================================
// FV-Julia Lambda & Closure Validation
// ==========================================

type LambdaTest struct {
	name       string
	code       string
	isValid    bool
	features   []string
	fv2Output  string
}

var lambdaTests = []LambdaTest{
	{
		name:    "Basic Lambda",
		code:    "let add = fn(x: Int) -> Int { x + 1 }",
		isValid: true,
		features: []string{
			"Lambda definition",
			"Type annotations",
			"Single parameter",
			"Function body",
		},
		fv2Output: "let add = fn(x:i32) i32 { x + 1 }",
	},
	{
		name:    "Lambda with Multiple Params",
		code:    "let multiply = fn(a: Int, b: Int) -> Int { a * b }",
		isValid: true,
		features: []string{
			"Multiple parameters",
			"Parameter separation",
			"Return type annotation",
		},
		fv2Output: "let multiply = fn(a:i32, b:i32) i32 { a * b }",
	},
	{
		name:    "Lambda with Closure",
		code:    "let factor = 2; let mul = fn(x: Int) -> Int { x * factor }",
		isValid: true,
		features: []string{
			"Variable capture",
			"Closure scope",
			"External reference",
		},
		fv2Output: "let factor = 2; let mul = fn(x:i32) i32 { x * factor }",
	},
	{
		name:    "Array Map with Lambda",
		code:    "let doubled = array.map(fn(x: Int) -> Int { x * 2 })",
		isValid: true,
		features: []string{
			"Higher-order function",
			"Method call with lambda",
			"Anonymous function",
		},
		fv2Output: "let doubled = array.map(fn(x:i32) i32 { x * 2 })",
	},
	{
		name:    "Array Filter with Lambda",
		code:    "let evens = nums.filter(fn(x: Int) -> Bool { x % 2 == 0 })",
		isValid: true,
		features: []string{
			"Predicate lambda",
			"Boolean return",
			"Filter operation",
		},
		fv2Output: "let evens = nums.filter(fn(x:i32) bool { x % 2 == 0 })",
	},
	{
		name:    "Array Reduce with Lambda",
		code:    "let sum = arr.reduce(0, fn(acc: Int, x: Int) -> Int { acc + x })",
		isValid: true,
		features: []string{
			"Accumulator function",
			"Two parameters",
			"Reduce operation",
		},
		fv2Output: "let sum = arr.reduce(0, fn(acc:i32, x:i32) i32 { acc + x })",
	},
	{
		name:    "Function Composition",
		code:    "let composed = compose(fn(x: Int) -> Int { x * 2 }, fn(y: Int) -> Int { y + 1 })",
		isValid: true,
		features: []string{
			"Nested lambdas",
			"Function argument",
			"Composition pattern",
		},
		fv2Output: "let composed = compose(fn(x:i32) i32 { x * 2 }, fn(y:i32) i32 { y + 1 })",
	},
	{
		name:    "Currying",
		code:    "let add = fn(a: Int) -> Function { fn(b: Int) -> Int { a + b } }",
		isValid: true,
		features: []string{
			"Higher-order return",
			"Nested function",
			"Curried function",
		},
		fv2Output: "let add = fn(a:i32) function { fn(b:i32) i32 { a + b } }",
	},
	{
		name:    "Lambda Type Inference",
		code:    "let infer = fn(x, y) { x + y }",
		isValid: true,
		features: []string{
			"Type inference",
			"Implicit types",
			"Binary operation",
		},
		fv2Output: "let infer = fn(x, y) { x + y }",
	},
	{
		name:    "Recursive Lambda",
		code:    "let factorial = fn(n: Int) -> Int { if n <= 1 then 1 else n * factorial(n - 1) end }",
		isValid: true,
		features: []string{
			"Recursive call",
			"Conditional",
			"Self-reference",
		},
		fv2Output: "let factorial = fn(n:i32) i32 { if n <= 1 then 1 else n * factorial(n - 1) end }",
	},
}

// ==========================================
// Lambda Validation Functions
// ==========================================

func isLambda(code string) bool {
	return strings.Contains(code, "fn(") && strings.Contains(code, "{")
}

func extractLambdaSignature(code string) string {
	// "let x = fn(a: Int, b: Int) -> Int { ... }" 에서
	// "fn(a: Int, b: Int) -> Int" 부분 추출
	start := strings.Index(code, "fn(")
	if start == -1 {
		return ""
	}

	// { 찾기
	end := strings.Index(code[start:], "{")
	if end == -1 {
		return ""
	}

	signature := code[start : start+end]
	return strings.TrimSpace(signature)
}

func mapLambdaType(lambdaSignature string) string {
	// "fn(a: Int, b: Int) -> Int" -> "fn(a:i32, b:i32) i32"
	result := lambdaSignature

	// 파라미터 부분 추출
	parenStart := strings.Index(result, "(")
	parenEnd := strings.LastIndex(result, ")")

	if parenStart >= 0 && parenEnd > parenStart {
		paramsPart := result[parenStart+1 : parenEnd]

		// 타입 매핑: "Int" -> "i32" 등
		paramsPart = strings.ReplaceAll(paramsPart, "Int", "i32")
		paramsPart = strings.ReplaceAll(paramsPart, "Float", "f64")
		paramsPart = strings.ReplaceAll(paramsPart, "String", "string")
		paramsPart = strings.ReplaceAll(paramsPart, "Bool", "bool")

		// 공백 제거 (": " -> ":")
		paramsPart = strings.ReplaceAll(paramsPart, ": ", ":")

		// 반환 타입 추출 및 매핑
		returnTypeStart := strings.Index(result, "->")
		var returnType string

		if returnTypeStart >= 0 {
			returnPart := result[returnTypeStart+2:]
			returnType = strings.TrimSpace(returnPart)

			// 반환 타입 매핑
			returnType = strings.ReplaceAll(returnType, "Int", "i32")
			returnType = strings.ReplaceAll(returnType, "Float", "f64")
			returnType = strings.ReplaceAll(returnType, "String", "string")
			returnType = strings.ReplaceAll(returnType, "Bool", "bool")
			returnType = strings.ReplaceAll(returnType, "Function", "function")

			return "fn(" + paramsPart + ") " + returnType
		}

		return "fn(" + paramsPart + ")"
	}

	return lambdaSignature
}

func validateLambdaSyntax(code string) []string {
	issues := []string{}

	if !isLambda(code) {
		issues = append(issues, "Not a lambda expression (missing 'fn(')")
		return issues
	}

	// 괄호 매칭 확인
	openParen := strings.Count(code, "(")
	closeParen := strings.Count(code, ")")
	if openParen != closeParen {
		issues = append(issues, fmt.Sprintf("Parenthesis mismatch: %d open, %d close", openParen, closeParen))
	}

